import{_ as a,o as n,c as r,a0 as t}from"./chunks/framework.DoRPXVp_.js";const p=JSON.parse('{"title":"Performance Benchmark Design","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0001-performance-benchmark-design.md","filePath":"adr/0001-performance-benchmark-design.md"}'),o={name:"adr/0001-performance-benchmark-design.md"};function s(i,e,d,c,l,h){return n(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="performance-benchmark-design" tabindex="-1">Performance Benchmark Design <a class="header-anchor" href="#performance-benchmark-design" aria-label="Permalink to &quot;Performance Benchmark Design&quot;">​</a></h1><p>We measure three dimensions — Time-to-First-Handshake (TTFH), WireGuard tunnel throughput, and control-plane API p99 latency — using agent-side instrumentation rather than external polling, and publish results as Shields.io badges backed by JSON files on the <code>gh-pages</code> branch.</p><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><p><strong>Agent-side instrumentation (chosen):</strong> The agent records <code>t0</code> at process start and emits <code>lattice_peer_handshake_duration_seconds</code> when <code>wgtypes.Peer.LastHandshakeTime</code> transitions from zero to non-zero. Results are pushed to VictoriaMetrics and also written to <code>gh-pages</code> JSON by CI.</p><p><strong>External observer polling (rejected):</strong> The test harness polls <code>wg show</code> in a loop and measures wall-clock time. Simpler to implement but includes container startup overhead (±500ms noise) and cannot be observed in production deployments.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><code>lattice_peer_handshake_duration_seconds</code> is a <strong>Community-visible metric</strong> — it must never be moved behind the Pro feature gate, as it is the primary signal that an installation is working correctly.</li><li>TTFH SLA tiers are: LAN ≤ 3 s, NAT ≤ 8 s, Relay ≤ 15 s.</li><li>CI benchmark runs weekly (<code>schedule</code>) plus on <code>workflow_dispatch</code>. A <strong>Benchmark SLA Gate</strong> (hard CI failure) is deliberately deferred until 4 weeks of baseline data are collected on shared GitHub Actions runners to avoid false positives from network jitter.</li><li>Benchmark results are committed to <code>gh-pages</code> as Shields.io endpoint JSON; README badges update automatically after each run.</li></ul>',7)])])}const u=a(o,[["render",s]]);export{p as __pageData,u as default};
